            path.add(node.value);
            Node parent = node.parent;
            while (parent != null && parent.value < value) {
                path.add(parent.value);
                node = parent;
                parent = node.parent;
            }
            if (parent != null && parent.value > value) {
                path.add(parent.value);
            }
        }
        return path;
    }

