```java
import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] strA = sc.nextLine().split(" ");

        int[] array = new int[strA.length];
        for (int k = 0; k < strA.length; k++)
            array[k] = Integer.parseInt(strA[k]);

        int pivotIndex = hoarePartition(array, 0, array.length - 1);
        System.out.println(Arrays.toString(array));
    }

    public static int hoarePartition(int[] array, int low, int high) {
        int pivot = array[(low + high) / 2]; // Choosing the middle element as pivot
        int i = low - 1;
        int j = high + 1;

        while (true) {
            do {
                i++;
            } while (array[i] < pivot);

            do {
                j--;
            } while (array[j] > pivot);

            if (i >= j) {
                return j;
            }

            // Swap array[i] and array[j]
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }
}
```

